insert into public.curated_question_catalog
(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance)
select source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance
from jsonb_to_recordset($questions$[{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","external_item_key":"pcac26-ti-seguranca-101-confidencialidade-need-to-know","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Confidencialidade e necessidade de conhecer","tested_topic":"Segurança da informação — confidencialidade","question_text":"Uma unidade policial mantém documentos com dados pessoais e informações sigilosas. Um servidor de outra unidade, embora possua credencial válida na rede institucional, solicita acesso a um procedimento sem relação com suas atribuições. A medida mais adequada é:\n\nA) liberar o acesso, pois a autenticação institucional é suficiente.\nB) compartilhar o arquivo por link público e registrar o envio.\nC) negar o acesso por ausência de necessidade funcional, observando as regras de autorização e o princípio da necessidade de conhecer.\nD) permitir a consulta desde que o servidor não faça download.\nE) liberar o acesso e solicitar que o usuário apague o histórico depois.","official_answer":"C","explanation":"A confidencialidade exige que a informação seja acessada apenas por pessoas autorizadas. A credencial prova a identidade, mas não concede acesso irrestrito a todos os procedimentos. A autorização deve considerar função, atribuição e necessidade concreta de conhecer o conteúdo.","legal_basis":[],"difficulty":"média","content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026","annex":"III","page":50,"kind":"original_question","review_note":"Questão autoral; enunciado, alternativa única e explicação conferidos para o item 6."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","external_item_key":"pcac26-ti-seguranca-102-integridade-hash","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Integridade, hash e verificação de arquivos","tested_topic":"Segurança da informação — integridade","question_text":"Durante a preservação de um arquivo digital, a equipe calcula seu resumo criptográfico (hash) no momento da coleta e volta a calculá-lo após a transferência. Os valores obtidos são diferentes. A conclusão tecnicamente adequada é:\n\nA) o arquivo foi necessariamente alterado de forma criminosa.\nB) há indicação de que o conteúdo não permaneceu idêntico, devendo-se investigar a divergência e documentar o procedimento.\nC) o hash comprova quem realizou a alteração.\nD) o arquivo está automaticamente autenticado porque o hash foi calculado duas vezes.\nE) a diferença demonstra que o algoritmo utilizado é de criptografia assimétrica.","official_answer":"B","explanation":"O hash permite comparar a integridade de conteúdos: valores diferentes indicam que os dados comparados não são idênticos, ressalvados erros de procedimento ou cálculo. A divergência não revela, sozinha, quem alterou o arquivo, quando ocorreu a mudança ou se houve intenção criminosa.","legal_basis":[],"difficulty":"média","content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026","annex":"III","page":50,"kind":"original_question","review_note":"Questão autoral; enunciado, alternativa única e explicação conferidos para o item 6."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","external_item_key":"pcac26-ti-seguranca-103-criptografia-simetrica-assimetrica","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Criptografia simétrica e assimétrica","tested_topic":"Segurança da informação — criptografia","question_text":"Sobre os modelos de criptografia, assinale a alternativa correta.\n\nA) A criptografia simétrica utiliza obrigatoriamente uma chave pública e uma chave privada distintas.\nB) A criptografia assimétrica utiliza a mesma chave secreta compartilhada para cifrar e decifrar.\nC) O hash é uma modalidade de criptografia assimétrica que permite recuperar o texto original.\nD) A criptografia simétrica utiliza a mesma chave para cifrar e decifrar, enquanto a assimétrica utiliza um par de chaves relacionadas.\nE) A criptografia dispensa o controle de acesso ao sistema que armazena os dados.","official_answer":"D","explanation":"Na criptografia simétrica, uma mesma chave secreta é utilizada na cifragem e na decifragem. Na assimétrica, há um par de chaves relacionadas, normalmente denominado pública e privada. Hash não é criptografia reversível e nenhuma dessas técnicas substitui a gestão de permissões.","legal_basis":[],"difficulty":"média","content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026","annex":"III","page":50,"kind":"original_question","review_note":"Questão autoral; enunciado, alternativa única e explicação conferidos para o item 6."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","external_item_key":"pcac26-ti-seguranca-104-backup-incremental-diferencial","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Backups completos, incrementais e diferenciais","tested_topic":"Segurança da informação — cópias de segurança","question_text":"Uma organização realiza um backup completo no domingo. Na segunda-feira, executa um backup incremental; na terça-feira, executa outro incremental. Considerando a definição usual desses métodos, o backup incremental de terça-feira registra:\n\nA) as alterações ocorridas desde o backup realizado imediatamente antes, isto é, desde o incremental de segunda-feira.\nB) todas as alterações desde o backup completo de domingo, como ocorre no diferencial.\nC) uma nova cópia integral de todos os dados, obrigatoriamente.\nD) somente os arquivos que nunca foram copiados anteriormente.\nE) apenas os arquivos excluídos desde domingo.","official_answer":"A","explanation":"O backup incremental copia as alterações desde o backup anterior, que pode ser completo ou incremental. O diferencial, por sua vez, acumula as alterações desde o último backup completo. Para restaurar uma cadeia incremental, em regra, são necessárias as cópias intermediárias pertinentes.","legal_basis":[],"difficulty":"alta","content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026","annex":"III","page":50,"kind":"original_question","review_note":"Questão autoral; enunciado, alternativa única e explicação conferidos para o item 6."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","external_item_key":"pcac26-ti-seguranca-105-tls-dados-em-transito","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Criptografia em trânsito e HTTPS/TLS","tested_topic":"Segurança da informação — proteção de comunicações","question_text":"Ao acessar um sistema institucional por HTTPS, a conexão utiliza TLS corretamente configurado. Qual afirmação descreve adequadamente a proteção oferecida?\n\nA) O protocolo impede qualquer tipo de fraude praticada pelo usuário.\nB) O conteúdo armazenado no servidor fica automaticamente criptografado em repouso.\nC) O uso de HTTPS torna desnecessários autenticação, autorização e registros de auditoria.\nD) O protocolo garante que o computador do usuário esteja livre de malware.\nE) A conexão protege a comunicação em trânsito, mas não substitui controles de acesso nem a proteção dos dados armazenados.","official_answer":"E","explanation":"HTTPS utiliza TLS para proteger a comunicação entre cliente e servidor, incluindo confidencialidade e integridade do canal e autenticação do servidor conforme a validação do certificado. Isso não garante a segurança do dispositivo, não criptografa automaticamente os dados em repouso e não substitui autorização ou auditoria.","legal_basis":[],"difficulty":"média","content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026","annex":"III","page":50,"kind":"original_question","review_note":"Questão autoral; enunciado, alternativa única e explicação conferidos para o item 6."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","external_item_key":"pcac26-ti-seguranca-106-resposta-incidente-preservacao-evidencias","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Resposta a incidentes e preservação de evidências","tested_topic":"Segurança da informação — resposta a incidentes","question_text":"Um computador utilizado em investigação apresenta sinais de comprometimento e contém arquivos potencialmente relevantes para um procedimento. Qual conduta inicial é mais adequada?\n\nA) formatar imediatamente o equipamento para eliminar o malware.\nB) apagar os registros do sistema para impedir vazamento de dados.\nC) acionar o procedimento institucional de resposta, conter o risco de forma controlada e preservar registros e evidências, documentando as ações realizadas.\nD) copiar todos os arquivos para uma conta pessoal na nuvem antes de comunicar o incidente.\nE) continuar utilizando normalmente o equipamento até que o problema impeça o trabalho.","official_answer":"C","explanation":"A resposta deve equilibrar contenção do incidente e preservação da evidência. Ações precipitadas, como formatar ou apagar registros, podem destruir vestígios relevantes. É necessário seguir o procedimento institucional, registrar horários e responsáveis, preservar logs e documentar cada intervenção.","legal_basis":[],"difficulty":"alta","content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026","annex":"III","page":50,"kind":"original_question","review_note":"Questão autoral; enunciado, alternativa única e explicação conferidos para o item 6."}}]$questions$::jsonb)
as q(source_id uuid,syllabus_topic_id uuid,external_item_key text,contest_name text,contest_year integer,career_name text,exam_board text,subject text,subtopic text,tested_topic text,question_text text,official_answer text,explanation text,legal_basis jsonb,difficulty text,content_status text,is_original boolean,didactic_provenance jsonb)
