 syllabus_topic_id=excluded.syllabus_topic_id,contest_name=excluded.contest_name,contest_year=excluded.contest_year,career_name=excluded.career_name,exam_board=excluded.exam_board,subject=excluded.subject,subtopic=excluded.subtopic,tested_topic=excluded.tested_topic,question_text=excluded.question_text,official_answer=excluded.official_answer,explanation=excluded.explanation,legal_basis=excluded.legal_basis,difficulty=excluded.difficulty,content_status=excluded.content_status,is_original=excluded.is_original,didactic_provenance=excluded.didactic_provenance;